// === Tab: mySketch ===
let rows = 120;
let cols = 240;
let radius = 300;
let t = 0, angleY = 0;

function setup(){
  createCanvas(800, 800, WEBGL);
  frameRate(60);
  smooth(0);
  noCursor();
}

function draw(){
  background(0);
  translate(width/2, height/2);
  rotateX(HALF_PI);
  rotateY(angleY);
  rotateZ(radians(-20));

  stroke(255);
  strokeWeight(0.5);

  let freqU = 16.0;
  let speed = 0.02;

  for(i=0; i<rows; i++){
    let phi = map(i,0,rows-1,-HALF_PI,HALF_PI);
    let y = radius*sin(phi);
    let r = radius*cos(phi);

    for(j=0; j<cols; j++){
      let theta = map(j,0,cols,0,TWO_PI);
      let x = r*cos(theta);
      let z = r*sin(theta);

      let mod1 = sin(t*freqU + j*0.2);
      let mod2 = sin(i*0.15 + t*8.0);
      let visible = (mod1 > 0.95) && (mod2 > 0.95);

      if(visible){
        line(x - 0.6, y, z, x + 0.6, y, z);
      }
    }
  }

  t += speed;
  angleY += 0.001;
}

